import ast
import os
import glob

keywords = ['create_', 'update_', 'delete_', 'save_', 'write_', 'POST', 'PUT', 'PATCH']

def analyze_file(filepath):
    with open(filepath, 'r') as f:
        content = f.read()

    try:
        tree = ast.parse(content)
    except Exception as e:
        print(f"Error parsing {filepath}: {e}")
        return []

    results = []

    # We want to find each FunctionDef and check if legacy_auth is called in it.
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef):
            # Check if legacy_auth is called inside this function
            has_legacy_auth = False
            for child in ast.walk(node):
                if isinstance(child, ast.Call) and isinstance(child.func, ast.Name) and child.func.id == 'legacy_auth':
                    has_legacy_auth = True
                    break

            if has_legacy_auth:
                # Find all source code for this function
                lines = content.splitlines()
                func_lines = lines[node.lineno - 1 : node.end_lineno]
                func_text = "\n".join(func_lines)

                # Check for keywords in the function's source code
                matched_keywords = []
                for kw in keywords:
                    if kw in func_text:
                        matched_keywords.append(kw)

                results.append({
                    'file': filepath,
                    'function': node.name,
                    'matched_keywords': matched_keywords,
                    'scope': 'write' if matched_keywords else 'read',
                    'text': func_text
                })
    return results

def main():
    all_results = []
    for filepath in glob.glob('app/**/*.py', recursive=True):
        if filepath == 'app/auth.py':
            continue
        res = analyze_file(filepath)
        all_results.extend(res)

    for r in all_results:
        print("="*60)
        print(f"File: {r['file']} | Function: {r['function']} | Scope: {r['scope']} (Matched: {r['matched_keywords']})")
        print("-" * 60)
        print(r['text'])
        print("="*60)
        print()

if __name__ == '__main__':
    main()

